import type { CSSProperties, ReactNode } from "react";
import { ARABIC, LATIN, LOCKUP, MARK } from "@/components/brand/wordmark-paths";

/**
 * Drawings for the brand book. Every number here comes from the mark's own
 * geometry (src/components/brand/wordmark-paths.ts, generated by
 * scripts/brand-assets.mts), so the construction drawing can't drift from the logo.
 * Artboards use fixed Night colours; figures on the page itself use the tokens.
 */

/** Deep indigo: the letter on lavender and white. */
export const INDIGO = "#1b1840";
/** The night artboard. */
export const NIGHT = "#141235";
export const LAVENDER = "#efedfb";
export const WHITE = "#ffffff";
/** The pupil on night (dark --saffron) and on light grounds (light --saffron). */
export const CORAL = "#ff5c7c";
export const CORAL_DEEP = "#e8436b";
/** Coral as small text on white (light --signal-hover). */
const CORAL_TEXT = "#c22a51";
const GRID = "#e1ddf5";
const GRID_STRONG = "#c3bcec";
const DIM = "#5f5a8c";
/** The app tile's ground: violet into navy. */
const TILE = ["#7564ee", "#1e2f86"] as const;

const rad = (a: number) => (a * Math.PI) / 180;
const onCircle = (c: { cx: number; cy: number; r: number }, a: number) => ({ x: c.cx + c.r * Math.cos(rad(a)), y: c.cy + c.r * Math.sin(rad(a)) });

type Ring = (typeof MARK)["outer"];
const ringPath = (g: Ring, turn = 0) => {
  const p0 = onCircle({ cx: MARK.cx, cy: MARK.cy, r: g.r }, g.from + turn);
  const p1 = onCircle({ cx: MARK.cx, cy: MARK.cy, r: g.r }, g.to + turn);
  return `M${p0.x} ${p0.y}A${g.r} ${g.r} 0 1 1 ${p1.x} ${p1.y}`;
};

/**
 * Focus: the two open rings and the point. `closed`, `flat`, `turn` and `dotAt`
 * exist only to draw what not to do.
 */
function MarkShapes({ fg = INDIGO, dot = CORAL_DEEP, closed = false, flat = false, turn = 0, dotAt }: { fg?: string; dot?: string; closed?: boolean; flat?: boolean; turn?: number; dotAt?: { cx: number; cy: number } }) {
  return (
    <>
      {[MARK.outer, MARK.inner].map((g) =>
        closed ? (
          <circle key={g.r} cx={MARK.cx} cy={MARK.cy} r={g.r} fill="none" stroke={fg} strokeWidth={g.w} strokeOpacity={flat ? 1 : g.opacity} />
        ) : (
          <path key={g.r} d={turn ? ringPath(g, turn) : g.d} fill="none" stroke={fg} strokeWidth={g.w} strokeOpacity={flat ? 1 : g.opacity} strokeLinecap="round" />
        ),
      )}
      <circle cx={dotAt?.cx ?? MARK.cx} cy={dotAt?.cy ?? MARK.cy} r={MARK.dot.r} fill={dot} />
    </>
  );
}

/** A 64-unit grid: a line every 4 units, stronger every 16. */
function Grid({ minor, major, size = 64 }: { minor: string; major: string; size?: number }) {
  const lines = Array.from({ length: size / 4 + 1 }, (_, i) => i * 4);
  return (
    <g>
      {lines.map((v) => (
        <g key={v} stroke={v % 16 === 0 ? major : minor} strokeWidth={v % 16 === 0 ? 0.16 : 0.1}>
          <line x1={v} y1={0} x2={v} y2={size} />
          <line x1={0} y1={v} x2={size} y2={v} />
        </g>
      ))}
    </g>
  );
}

/**
 * The mark drawn on its grid: both rings with their radii and widths, the
 * gaps they open towards, the round ends and the point at the centre.
 */
export function MarkConstruction({ labels }: { labels: { units: string; outer: string; inner: string; stroke: string; point: string; gap: string } }) {
  const { outer, inner, cx, cy, dot } = MARK;
  const t = { fontSize: 2.5, fill: DIM, fontFamily: "var(--font-sans)" } as const;
  const dim = { stroke: DIM, strokeWidth: 0.16 } as const;
  const guide = { fill: "none", stroke: CORAL_DEEP, strokeWidth: 0.24, strokeDasharray: "1 0.8" } as const;
  const ends = [outer, inner].flatMap((g) => [onCircle({ cx, cy, r: g.r }, g.from), onCircle({ cx, cy, r: g.r }, g.to)]);
  const gapMid = onCircle({ cx, cy, r: outer.r + 6 }, (outer.to - 360 + outer.from) / 2);
  return (
    <svg viewBox="-22 -11 108 86" className="h-auto w-full" role="img" aria-label={[labels.units, labels.outer, labels.inner, labels.stroke, labels.gap, labels.point].join(", ")} direction="ltr">
      <Grid minor={GRID} major={GRID_STRONG} />
      <rect x={0} y={0} width={64} height={64} fill="none" stroke={GRID_STRONG} strokeWidth={0.22} />
      <MarkShapes />
      {/* The full circles each ring is cut from, and the centre they share. */}
      <circle cx={cx} cy={cy} r={outer.r} {...guide} />
      <circle cx={cx} cy={cy} r={inner.r} {...guide} />
      {ends.map((p) => (
        <circle key={`${p.x}-${p.y}`} cx={p.x} cy={p.y} r={3.6} fill="none" stroke={CORAL_DEEP} strokeWidth={0.22} strokeDasharray="0.8 0.6" />
      ))}
      <g stroke={WHITE} strokeWidth={0.26} strokeLinecap="round">
        <line x1={cx - 0.9} y1={cy} x2={cx + 0.9} y2={cy} />
        <line x1={cx} y1={cy - 0.9} x2={cx} y2={cy + 0.9} />
      </g>
      {/* 64 across the top */}
      <g {...dim}>
        <line x1={0} y1={-4} x2={64} y2={-4} />
        <line x1={0} y1={-5.2} x2={0} y2={-2.8} />
        <line x1={64} y1={-5.2} x2={64} y2={-2.8} />
      </g>
      <text x={32} y={-5.8} textAnchor="middle" {...t}>
        {labels.units}
      </text>
      {/* Radii, labelled on the right */}
      <g {...dim} strokeDasharray="0.5 0.5">
        <line x1={cx + outer.r + outer.w / 2 + 0.6} y1={cy - 8} x2={67} y2={cy - 8} />
        <line x1={cx + inner.r + inner.w / 2 + 0.6} y1={cy + 2} x2={67} y2={cy + 2} />
        <line x1={cx + dot.r + 0.6} y1={cy + 12} x2={67} y2={cy + 12} />
      </g>
      <text x={68} y={cy - 7.1} {...t}>
        {labels.outer}
      </text>
      <text x={68} y={cy + 2.9} {...t}>
        {labels.inner}
      </text>
      <text x={68} y={cy + 12.9} {...t}>
        {labels.point}
      </text>
      {/* Stroke width across the bottom of the outer ring */}
      <g {...dim}>
        <line x1={cx} y1={cy + outer.r - outer.w / 2} x2={cx} y2={cy + outer.r + outer.w / 2} stroke={WHITE} strokeWidth={0.3} />
        <line x1={cx + 1} y1={cy + outer.r + outer.w / 2} x2={cx + 1} y2={68} strokeDasharray="0.5 0.5" />
      </g>
      <text x={cx + 2} y={70.5} {...t}>
        {labels.stroke}
      </text>
      {/* The gap both rings open towards */}
      <text x={gapMid.x - 1} y={gapMid.y + 3} textAnchor="end" {...t}>
        {labels.gap}
      </text>
    </svg>
  );
}

/** The mark on its grid, large, in white on night with the coral point, for the cover. */
export function CoverMark() {
  return (
    <svg viewBox="-8 -8 80 80" className="h-auto w-full" aria-hidden>
      <g transform="translate(-8 -8)">
        {Array.from({ length: 21 }, (_, i) => i * 4).map((v) => (
          <g key={v} stroke={WHITE} strokeOpacity={v % 16 === 0 ? 0.12 : 0.05} strokeWidth={0.12}>
            <line x1={v} y1={0} x2={v} y2={80} />
            <line x1={0} y1={v} x2={80} y2={v} />
          </g>
        ))}
      </g>
      {/* The full circles the rings are cut from, faint. */}
      {[MARK.outer, MARK.inner].map((g) => (
        <circle key={g.r} cx={MARK.cx} cy={MARK.cy} r={g.r} fill="none" stroke={WHITE} strokeOpacity={0.22} strokeWidth={0.18} strokeDasharray="0.9 0.9" />
      ))}
      <circle cx={MARK.cx} cy={MARK.cy} r={MARK.dot.r * 2.4} fill={CORAL} opacity={0.26} style={{ filter: "blur(3px)" }} />
      <MarkShapes fg={WHITE} dot={CORAL} />
    </svg>
  );
}

/**
 * Focus, explained: the faint field of what we don't know yet, the rings
 * closing in, and the point we can stand behind. White on night, labelled.
 */
export function FocusFigure({ labels }: { labels: { field: string; rings: string; point: string } }) {
  const t = { fontSize: 3.4, fill: WHITE, fontFamily: "var(--font-sans)", fontWeight: 600 } as const;
  const field = [30, 36, 42].map((r, i) => (
    <circle key={r} cx={MARK.cx} cy={MARK.cy} r={r} fill="none" stroke={WHITE} strokeOpacity={0.08 - i * 0.02} strokeWidth={1.4} strokeDasharray={`${4 + i * 3} ${3 + i * 2}`} />
  ));
  return (
    <svg viewBox="-12 -12 112 88" className="h-auto w-full" role="img" aria-label={`${labels.field}, ${labels.rings}, ${labels.point}`} direction="ltr">
      {field}
      <circle cx={MARK.cx} cy={MARK.cy} r={MARK.dot.r * 2.6} fill={CORAL} opacity={0.28} style={{ filter: "blur(3px)" }} />
      <MarkShapes fg={WHITE} dot={CORAL} />
      <g stroke={WHITE} strokeOpacity={0.6} strokeWidth={0.22} fill="none">
        <line x1={MARK.cx + 36} y1={MARK.cy - 18} x2={82} y2={MARK.cy - 18} />
        <line x1={MARK.cx + MARK.outer.r + 3.6} y1={MARK.cy} x2={82} y2={MARK.cy} />
        <line x1={MARK.cx + MARK.dot.r + 0.6} y1={MARK.cy + 2} x2={MARK.cx + 10} y2={MARK.cy + 18} />
        <line x1={MARK.cx + 10} y1={MARK.cy + 18} x2={82} y2={MARK.cy + 18} />
      </g>
      <text x={83.5} y={MARK.cy - 16.8} {...t} fillOpacity={0.75}>
        {labels.field}
      </text>
      <text x={83.5} y={MARK.cy + 1.2} {...t}>
        {labels.rings}
      </text>
      <text x={83.5} y={MARK.cy + 19.2} {...t} fill={CORAL}>
        {labels.point}
      </text>
    </svg>
  );
}

/**
 * The supergraphic: the outer ring, drawn very large as an open arc that
 * sweeps in from the edge, in the app tile's violet and navy.
 */
export function Sweep({ className }: { className?: string }) {
  const k = 3.4;
  return (
    <svg viewBox="0 0 160 90" preserveAspectRatio="xMidYMid slice" className={className} aria-hidden>
      <defs>
        <linearGradient id="bb-sweep" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0" stopColor={TILE[0]} stopOpacity={0.9} />
          <stop offset="1" stopColor={TILE[1]} stopOpacity={0.15} />
        </linearGradient>
      </defs>
      <g transform={`translate(${118 - MARK.cx * k} ${46 - MARK.cy * k}) scale(${k})`}>
        <path d={MARK.outer.d} fill="none" stroke="url(#bb-sweep)" strokeWidth={MARK.outer.w} strokeLinecap="round" />
        <path d={MARK.inner.d} fill="none" stroke="url(#bb-sweep)" strokeWidth={MARK.inner.w} strokeLinecap="round" strokeOpacity={0.6} />
      </g>
    </svg>
  );
}

/**
 * One skill, measured: the band of plausible levels after each answer,
 * narrowing towards the estimate, drawn bottom-up in the page's own tokens so
 * it follows the theme. The estimate wears the pupil's coral.
 */
export function NarrowingFigure({ rows, estimate, scale, rtl }: { rows: { label: string; lo: number; hi: number }[]; estimate: { label: string; value: number }; scale: [string, string]; rtl: boolean }) {
  const W = 150;
  const labelW = 44;
  const x0 = labelW + 6;
  const x1 = W - 5;
  const lx = (level: number) => x0 + ((level - 1) / 4) * (x1 - x0);
  const X = (x: number) => (rtl ? W - x : x);
  const h = 10;
  const rowY = (i: number) => 70 - i * 18; // i = 0 is the first answer, at the bottom
  const all = [...rows.map((r) => ({ ...r, dot: false })), { label: estimate.label, lo: estimate.value, hi: estimate.value, dot: true }];
  const text = { fontSize: 5, fill: "var(--text-tertiary)", fontFamily: "var(--font-sans)" } as const;
  // direction="ltr" so text-anchor means the same thing in both languages; Arabic still shapes right to left.
  return (
    <svg viewBox={`0 0 ${W} 98`} className="h-auto w-full overflow-visible" role="img" aria-label={all.map((r) => r.label).join(", ")} direction="ltr">
      {all.map((r, i) => {
        const y = rowY(i);
        const a = X(lx(r.lo));
        const b = X(lx(r.hi));
        return (
          <g key={r.label}>
            <line x1={X(x0)} y1={y} x2={X(x1)} y2={y} stroke="var(--chart-grid)" strokeWidth={0.5} />
            {[1, 2, 3, 4, 5].map((l) => (
              <line key={l} x1={X(lx(l))} y1={y - 1.6} x2={X(lx(l))} y2={y + 1.6} stroke="var(--mark-muted)" strokeWidth={0.35} />
            ))}
            {r.dot ? (
              <circle cx={a} cy={y} r={h / 2} fill="var(--signal)" style={{ filter: "drop-shadow(0 0 2.5px var(--signal))" }} />
            ) : (
              <rect x={Math.min(a, b)} y={y - h / 2} width={Math.abs(b - a)} height={h} rx={h / 2} fill="var(--accent)" opacity={0.55 + i * 0.15} />
            )}
            <text x={rtl ? W : 0} y={y + 1.7} textAnchor={rtl ? "end" : "start"} {...text} fill={r.dot ? "var(--text)" : "var(--text-tertiary)"} fontWeight={r.dot ? 600 : 400}>
              {r.label}
            </text>
          </g>
        );
      })}
      {[1, 2, 3, 4, 5].map((l) => (
        <text key={l} x={X(lx(l))} y={86} textAnchor="middle" {...text} fontSize={4.4} className="tabular">
          {l}
        </text>
      ))}
      <text x={X(x0)} y={94.5} textAnchor={rtl ? "end" : "start"} {...text} fontSize={4}>
        {scale[0]}
      </text>
      <text x={X(x1)} y={94.5} textAnchor={rtl ? "start" : "end"} {...text} fontSize={4}>
        {scale[1]}
      </text>
    </svg>
  );
}

type LockupVariant = "both" | "latin" | "arabic";

/**
 * The horizontal lockups as scripts/brand-assets.mts draws them (the ʿayn,
 * aalim, a rounded hairline, عالم; sizes in units of the Latin height), in
 * any colours. Arabic alone puts the mark on the right, where reading starts.
 */
function lockup(variant: LockupVariant) {
  const H = LATIN.height;
  const mark = H * LOCKUP.mark;
  const gap = H * LOCKUP.gap;
  const scale = (H * LOCKUP.arabic) / ARABIC.baseline;
  const latinOnly = variant === "latin";
  const arabicOnly = variant === "arabic";
  const markTop = (H - mark) / 2;
  const u = mark / 64;
  let x = 0;
  const at: { mark?: number; latin?: number; rule?: number; arabic?: number } = {};
  if (!arabicOnly) {
    at.mark = x - MARK.ink.x0 * u;
    x += (MARK.ink.x1 - MARK.ink.x0) * u + gap;
    at.latin = x;
    x += LATIN.width;
  }
  if (variant === "both") {
    x += H * LOCKUP.rule;
    at.rule = x;
    x += H * 0.07 + H * LOCKUP.rule;
  }
  if (!latinOnly) {
    at.arabic = x;
    x += ARABIC.width * scale;
  }
  if (arabicOnly) {
    x += H * LOCKUP.arabicGap;
    at.mark = x - MARK.ink.x0 * u;
    x += (MARK.ink.x1 - MARK.ink.x0) * u;
  }
  const top = Math.min(markTop + MARK.ink.y0 * u, latinOnly ? 0 : H - H * LOCKUP.arabic);
  const bottom = Math.max(H, markTop + MARK.ink.y1 * u, latinOnly ? 0 : H - ARABIC.baseline * scale + ARABIC.height * scale);
  // Placed by its ink, so the box starts and ends where the drawing does.
  const left = 0;
  const right = x;
  const parts = (fg: string, dot: string): ReactNode => (
    <>
      <g transform={`translate(${at.mark} ${markTop}) scale(${mark / 64})`}>
        <MarkShapes fg={fg} dot={dot} />
      </g>
      {at.latin !== undefined ? <path transform={`translate(${at.latin} 0)`} d={LATIN.d} fill={fg} /> : null}
      {at.rule !== undefined ? <rect x={at.rule} y={H * 0.12} width={H * 0.07} height={H * 0.88} rx={H * 0.035} fill={fg} opacity={0.24} /> : null}
      {at.arabic !== undefined ? (
        <g transform={`translate(${at.arabic} ${H - ARABIC.baseline * scale}) scale(${scale})`}>
          <path d={ARABIC.d} fill={fg} />
        </g>
      ) : null}
    </>
  );
  return { H, left, width: right - left, top, height: bottom - top, parts };
}

/** A lockup in fixed brand colours, drawn live (no font needed). */
export function LockupArt({ variant = "both", fg = INDIGO, dot = CORAL_DEEP, className, style }: { variant?: LockupVariant; fg?: string; dot?: string; className?: string; style?: CSSProperties }) {
  const l = lockup(variant);
  const pad = l.H * 0.06;
  return (
    <svg viewBox={`${l.left - pad} ${l.top - pad} ${l.width + pad * 2} ${l.height + pad * 2}`} className={className} style={style} role="img" aria-label="Aalim">
      {l.parts(fg, dot)}
    </svg>
  );
}

/** Clear space: x (the height of aalim) on every side of the lockup. */
export function ClearSpace({ x }: { x: string }) {
  const l = lockup("both");
  const { H, width, top, height } = l;
  const pad = H * 0.06;
  const vb = { x: l.left - pad, y: top - pad, w: width + pad * 2, h: height + pad * 2 };
  const m = H * 2.2;
  const zone = { x: vb.x - H, y: vb.y - H, w: vb.w + H * 2, h: vb.h + H * 2 };
  const sq = (cx: number, cy: number, key: string) => (
    <g key={key}>
      <rect x={cx - H / 2} y={cy - H / 2} width={H} height={H} rx={H * 0.12} fill={CORAL_DEEP} fillOpacity={0.12} stroke={CORAL_DEEP} strokeWidth={H * 0.025} />
      <text x={cx} y={cy + H * 0.16} textAnchor="middle" fontSize={H * 0.42} fill={CORAL_TEXT} fontFamily="var(--font-sans)" fontStyle="italic" fontWeight={600}>
        {x}
      </text>
    </g>
  );
  return (
    <svg viewBox={`${zone.x - m} ${zone.y - m * 0.6} ${zone.w + m * 2} ${zone.h + m * 1.2}`} className="h-auto w-full" role="img" aria-label={x} direction="ltr">
      <rect x={zone.x} y={zone.y} width={zone.w} height={zone.h} rx={H * 0.2} fill="none" stroke={DIM} strokeWidth={H * 0.03} strokeDasharray={`${H * 0.12} ${H * 0.1}`} />
      <rect x={vb.x} y={vb.y} width={vb.w} height={vb.h} fill="none" stroke={GRID_STRONG} strokeWidth={H * 0.02} />
      {l.parts(INDIGO, CORAL_DEEP)}
      {sq(zone.x + H / 2, vb.y + vb.h / 2, "l")}
      {sq(zone.x + zone.w - H / 2, vb.y + vb.h / 2, "r")}
      {sq(vb.x + vb.w * 0.36, zone.y + H / 2, "t")}
      {sq(vb.x + vb.w * 0.36, zone.y + zone.h - H / 2, "b")}
    </svg>
  );
}

/**
 * The mark in fixed brand colours (for artboards), or in tokens when given CSS
 * variables. `closeHead` and `pupil` draw misuse examples only.
 */
export function Mark({ fg = INDIGO, dot = CORAL_DEEP, closed, flat, turn, dotAt, className, style }: { fg?: string; dot?: string; closed?: boolean; flat?: boolean; turn?: number; dotAt?: { cx: number; cy: number }; className?: string; style?: CSSProperties }) {
  return (
    <svg viewBox="0 0 64 64" className={className} style={style} aria-hidden>
      <MarkShapes fg={fg} dot={dot} closed={closed} flat={flat} turn={turn} dotAt={dotAt} />
    </svg>
  );
}

/** "aalim" as a drawing (no live text), for colour samples. */
export function WordmarkShape({ fill, className }: { fill: string; className?: string }) {
  return (
    <svg viewBox={`0 0 ${LATIN.width} ${LATIN.height}`} className={className} aria-hidden>
      <path d={LATIN.d} fill={fill} />
    </svg>
  );
}

/**
 * The two wordmarks on their shared baseline, with the guides that set them:
 * the top of aalim (the l's ascender), the baseline, and the alif of عالم
 * rising a little above the ascender.
 */
export function WordmarkGuides({ labels }: { labels: { ascender: string; baseline: string; rise: string } }) {
  const H = LATIN.height;
  const scale = (H * LOCKUP.arabic) / ARABIC.baseline;
  const dy = H - ARABIC.baseline * scale;
  const ruleX = LATIN.width + H * LOCKUP.rule;
  const arX = ruleX + H * 0.07 + H * LOCKUP.rule;
  const width = arX + ARABIC.width * scale;
  const bottom = dy + ARABIC.height * scale;
  const fs = H * 0.19;
  const left = -H * 0.25;
  const right = width + H * 2.1;
  const lx = width + H * 0.3;
  // The ascender and alif lines are only 6% apart: one label sits above its line, the other below.
  // An Arabic label is laid out right to left (so "+6%" stays with its word), still starting at lx.
  const label = (y: number, text: string, color = DIM) => {
    const arabic = /[؀-ۿ]/.test(text);
    return (
      <text x={lx} y={y} fontSize={fs} fill={color} fontFamily="var(--font-sans)" direction={arabic ? "rtl" : undefined} textAnchor={arabic ? "end" : "start"}>
        {text}
      </text>
    );
  };
  return (
    <svg viewBox={`${left} ${dy - H * 0.4} ${right - left} ${bottom - dy + H * 0.65}`} className="h-auto w-full" role="img" aria-label={`${labels.ascender}, ${labels.baseline}, ${labels.rise}`} direction="ltr">
      <g strokeWidth={H * 0.012}>
        <line x1={left} y1={0} x2={width + H * 0.2} y2={0} stroke={GRID_STRONG} />
        <line x1={left} y1={H} x2={width + H * 0.2} y2={H} stroke={GRID_STRONG} />
        <line x1={arX - H * 0.1} y1={dy} x2={width + H * 0.2} y2={dy} stroke={CORAL_DEEP} strokeDasharray={`${H * 0.05} ${H * 0.04}`} />
      </g>
      <path d={LATIN.d} fill={INDIGO} />
      <rect x={ruleX} y={H * 0.12} width={H * 0.07} height={H * 0.88} rx={H * 0.035} fill={INDIGO} opacity={0.24} />
      <g transform={`translate(${arX} ${dy}) scale(${scale})`}>
        <path d={ARABIC.d} fill={INDIGO} />
      </g>
      {label(dy - fs * 0.35, labels.rise, CORAL_TEXT)}
      {label(fs * 1.05, labels.ascender)}
      {label(H + fs * 0.35, labels.baseline)}
    </svg>
  );
}
